public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    if (actualTypeArguments == null || actualTypeArguments.length == 0) {
        return null;
    }

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArgument = actualTypeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else {
            return null; // Cannot resolve other types of Type
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    GenericDeclaration genericDeclaration = typeVariable.getGenericDeclaration();
    if (!(genericDeclaration instanceof Class)) {
        return null;
    }

    Class<?> declaringClass = (Class<?>) genericDeclaration;
    Type[] bounds = typeVariable.getBounds();
    Class<?>[] boundClasses = new Class<?>[bounds.length];
    for (int i = 0; i < bounds.length; i++) {
        if (bounds[i] instanceof Class) {
            boundClasses[i] = (Class<?>) bounds[i];
        } else {
            return null; // Cannot resolve other types of Type
        }
    }

    if (declaringClass.equals(targetType)) {
        return boundClasses[0]; // Assuming the first bound is the one we want
    }

    // Recursively search the superclass and interfaces
    Class<?> superclass = targetType.getSuperclass();
    if (superclass != null) {
        Class<?> resolved = resolveTypeVariableInHierarchy(typeVariable, superclass);
        if (resolved != null) {
            return resolved;
        }
    }

    for (Class<?> interfaceClass : targetType.getInterfaces()) {
        Class<?> resolved = resolveTypeVariableInHierarchy(typeVariable, interfaceClass);
        if (resolved != null) {
            return resolved;
        }
    }

    return null;
}

private static Class<?> resolveTypeVariableInHierarchy(TypeVariable<?> typeVariable, Class<?> clazz) {
    Type genericSuperclass = clazz.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        for (int i = 0; i < typeVariables.length; i++) {
            if (typeVariable.equals(typeVariables[i])) {
                Type actualTypeArgument = actualTypeArguments[i];
                if (actualTypeArgument instanceof Class) {
                    return (Class<?>) actualTypeArgument;
                } else if (actualTypeArgument instanceof TypeVariable) {
                    return resolveTypeVariable((TypeVariable<?>) actualTypeArgument, clazz.getSuperclass());
                }
            }
        }
    }

    for (Type genericInterface : clazz.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericInterface;
            TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

            for (int i = 0; i < typeVariables.length; i++) {
                if (typeVariable.equals(typeVariables[i])) {
                    Type actualTypeArgument = actualTypeArguments[i];
                    if (actualTypeArgument instanceof Class) {
                        return (Class<?>) actualTypeArgument;
                    } else if (actualTypeArgument instanceof TypeVariable) {
                        return resolveTypeVariable((TypeVariable<?>) actualTypeArgument, (Class<?>) parameterizedType.getRawType());
                    }
                }
            }
        }
    }

    Class<?> superclass = clazz.getSuperclass();
    if (superclass != null) {
        return resolveTypeVariableInHierarchy(typeVariable, superclass);
    }

    return null;
}

