public long readLong(final int offset){
    try {
        if (offset < 0 || offset + 8 > this.b.length) {
            throw new IllegalArgumentException("Invalid offset for reading a long value.");
        }
        return ((this.b[offset] & 0xFFL) << 56) |
               ((this.b[offset + 1] & 0xFFL) << 48) |
               ((this.b[offset + 2] & 0xFFL) << 40) |
               ((this.b[offset + 3] & 0xFFL) << 32) |
               ((this.b[offset + 4] & 0xFFL) << 24) |
               ((this.b[offset + 5] & 0xFFL) << 16) |
               ((this.b[offset + 6] & 0xFFL) << 8) |
               (this.b[offset + 7] & 0xFFL);
    } catch (Exception e) {
        throw new RuntimeException("Error reading long value at offset: " + offset, e);
    }
}

