public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        final int length = str.length();
        int offset = 0;
        LinkedBuffer current = lb;

        while (offset < length) {
            int remaining = current.limit() - current.offset();
            if (remaining == 0) {
                current = current.next = session.nextBuffer();
                remaining = current.limit() - current.offset();
            }

            int i = offset;
            while (i < length && remaining > 0) {
                char c = str.charAt(i);
                if (c < 0x80) {
                    current.buffer[current.offset++] = (byte) c;
                    remaining--;
                } else if (c < 0x800) {
                    if (remaining < 2) break;
                    current.buffer[current.offset++] = (byte) (0xc0 | (c >> 6));
                    current.buffer[current.offset++] = (byte) (0x80 | (c & 0x3f));
                    remaining -= 2;
                } else if (Character.isSurrogate(c)) {
                    if (remaining < 4) break;
                    char low;
                    if (i + 1 == length || !Character.isSurrogatePair(c, (low = str.charAt(i + 1)))) {
                        throw new IllegalArgumentException("Unpaired surrogate at index " + i);
                    }
                    int codePoint = Character.toCodePoint(c, low);
                    current.buffer[current.offset++] = (byte) (0xf0 | (codePoint >> 18));
                    current.buffer[current.offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                    current.buffer[current.offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                    current.buffer[current.offset++] = (byte) (0x80 | (codePoint & 0x3f));
                    remaining -= 4;
                    i++;
                } else {
                    if (remaining < 3) break;
                    current.buffer[current.offset++] = (byte) (0xe0 | (c >> 12));
                    current.buffer[current.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                    current.buffer[current.offset++] = (byte) (0x80 | (c & 0x3f));
                    remaining -= 3;
                }
                i++;
            }
            offset = i;
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer", e);
    }
}

