private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
        } else { // Field descriptor
            popType(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'I': case 'S': case 'Z':
            // These are all single-word types
            index++;
            break;
        case 'D': case 'J':
            // These are double-word types
            index++;
            break;
        case 'L':
            // Object type, skip to the end of the class name
            index = descriptor.indexOf(';', index) + 1;
            if (index == 0) {
                throw new IllegalArgumentException("Invalid object type descriptor");
            }
            break;
        case '[':
            // Array type, skip to the type of the array
            index = popType(descriptor, index + 1);
            break;
        default:
            throw new IllegalArgumentException("Unknown type descriptor: " + descriptor.charAt(index));
    }
    return index;
}

