public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        if (buf == null) {
            throw new IllegalArgumentException("Buffer cannot be null");
        }
        if (nameStart < 0 || nameStart >= buf.length()) {
            throw new IllegalArgumentException("nameStart is out of buffer bounds");
        }
        // Assuming we want to abbreviate by taking the first character and the last character
        // and placing a dot in between if the name length is more than 1
        int length = buf.length();
        if (length - nameStart > 1) {
            char firstChar = buf.charAt(nameStart);
            char lastChar = buf.charAt(length - 1);
            buf.replace(nameStart, length, "" + firstChar + "." + lastChar);
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

